-- +goose Up
-- Mental models are curated, high-quality summaries about a specific topic,
-- generated by a reflect call and stored for fast retrieval. Unlike facts
-- (extracted from episodes) and reflect answers (generated on demand), a
-- mental model is a persistent artifact: it is created once, refreshed when
-- new memories arrive, and searched first in reflect because it represents
-- the most reliable synthesized knowledge about its topic.
CREATE TABLE mental_models (
    id                 BIGSERIAL    PRIMARY KEY,
    namespace_id       BIGINT       NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
    name               TEXT         NOT NULL,
    source_query       TEXT         NOT NULL,
    content            TEXT         NOT NULL DEFAULT '',
    embedding          vector       NULL,
    embedding_model    TEXT         NULL,
    tags               TEXT[]       NOT NULL DEFAULT '{}',
    max_tokens         INT          NOT NULL DEFAULT 2048,
    last_refreshed_at  TIMESTAMPTZ  NULL,
    created_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    deleted_at         TIMESTAMPTZ  NULL
);

CREATE INDEX ON mental_models (namespace_id, deleted_at);
CREATE INDEX ON mental_models (namespace_id, name) WHERE deleted_at IS NULL;
CREATE INDEX ON mental_models USING gin (tags) WHERE deleted_at IS NULL;

-- +goose Down
DROP TABLE IF EXISTS mental_models;
